example.code:
[BinaryParsable]
public readonly partial struct PacketHeader
{
    public U16BE Version { get; init; }
    public U32BE MessageType { get; init; }
    public U16BE PayloadLength { get; init; }
    
    [BinaryIgnore]
    public bool IsValid => Version.Value == 0x0100;
}

// Usage:
if (PacketHeader.TryParse(data, out var header, out int consumed))
{
    Console.WriteLine($"Version: {header.Version.Value}");
}

[BinaryWritable]
public readonly partial struct PacketHeader : IBinarySerializable
{
    public U16BE Version { get; init; }
    public U32BE MessageType { get; init; }
    public U16BE PayloadLength { get; init; }
}

// Usage with ZA.Bytes():
var header = new PacketHeader { Version = new(1), MessageType = new(42), PayloadLength = new(100) };
using var bytes = ZA.Bytes(header);

[BinaryParsable]
public readonly partial struct ReorderedPacket
{
    [BinaryOrder(2)]  // Read third
    public U16BE Checksum { get; init; }
    
    [BinaryOrder(0)]  // Read first
    public U16BE Type { get; init; }
    
    [BinaryOrder(1)]  // Read second
    public U32BE Length { get; init; }
}

[BinaryParsable]
public readonly partial struct Message
{
    public U16BE Type { get; init; }
    public U16BE Length { get; init; }
    
    [BinaryIgnore]
    public bool IsControl => Type.Value < 100;
    
    [BinaryIgnore]
    public DateTime ParsedAt { get; init; } = DateTime.UtcNow;
}

[BinaryParsable]
public readonly partial struct MacAddress
{
    [BinaryFixedLength(6)]
    public byte[] Address { get; init; }
}

[BinaryParsable]
public readonly partial struct FlagsPacket
{
    [BinaryField(BitCount = 4, PaddingBits = 4)]  // 4 bits + skip 4 reserved → byte-aligned
    public byte Flags { get; init; }
    
    public U32BE Payload { get; init; }         // 4 bytes
}

[BinaryParsable]
public readonly partial struct Message
{
    [StringLengthVarInt]
    public string Name { get; init; }  // VarInt length + UTF-8 bytes
}

public readonly struct NetworkHeader : IBinarySerializable
{
    public ushort Type { get; init; }
    public uint Length { get; init; }
    
    public bool TryGetWrittenSize(out int size) { size = 6; return true; }
    
    public bool TryWrite(Span<byte> destination, out int bytesWritten)
    {
        if (destination.Length < 6) { bytesWritten = 0; return false; }
        BinaryPrimitives.WriteUInt16BigEndian(destination, Type);
        BinaryPrimitives.WriteUInt32BigEndian(destination[2..], Length);
        bytesWritten = 6;
        return true;
    }
}

public readonly struct IpAddress : IStringSize, ISpanFormattable
{
    public byte A, B, C, D;
    
    // Exact calculation: count digits in each octet
    public bool TryGetStringSize(ReadOnlySpan<char> format, IFormatProvider? provider, out int size)
    {
        // Calculate actual size: each octet's digit count + 3 dots
        size = DigitCount(A) + DigitCount(B) + DigitCount(C) + DigitCount(D) + 3;
        return true;
    }
    
    private static int DigitCount(byte b) => b < 10 ? 1 : b < 100 ? 2 : 3;
    
    public bool TryFormat(Span<char> dest, out int written, ...)
    {
        // Actual formatting logic
    }
}

// Preferred: Use attribute (generator creates TryParse automatically)
[BinaryParsable]
public readonly partial struct PacketHeader
{
    public U16BE Version { get; init; }
    public U32BE Length { get; init; }
}

// The generated code includes:
// - static bool TryParse(ReadOnlySpan<byte>, out PacketHeader, out int)
// - static PacketHeader Parse(ReadOnlySpan<byte>)
// - static int FixedSize { get; }

member.summary:
Creates a lazily-evaluated formatted string with captured state. Use with a static lambda to avoid per-call closure allocation:
LazyString.FormatLazy((srcPort, dstPort), static s => ZA.String("Src: ", s.Item1, ", Dst: ", s.Item2));
The value is boxed once into the internal storage. The delegate should be static so no closure object is allocated. This reduces allocations from 2 (Func + closure) to 1 (boxed state) per call.

remarks.code:
Span<byte> buffer = stackalloc byte[256];
var builder = new SpanBytesBuilder(buffer);
builder.AppendUInt16BigEndian(0x1234);
builder.AppendUtf8("Hello");
ReadOnlySpan<byte> result = builder.AsSpan();

Span<char> buffer = stackalloc char[128];
var builder = new SpanStringBuilder(buffer);
builder.Append("Value: ");
builder.Append(42);
ReadOnlySpan<char> result = builder.AsSpan();

 using TempBytes temp = ZA.Utf8("User ", userId, " logged in");
 ReadOnlySpan<byte> span = temp.AsSpan();

 // Write directly to stream without allocation
 stream.Write(span);

 using TempBytes temp = ZA.Utf8("User ", userId, " logged in");
 ReadOnlySpan<byte> span = temp.AsSpan();

 // Write directly to stream without allocation
 stream.Write(span);

using var builder = TempBytesBuilder.Create();
builder.AppendUInt16BigEndian(0x0100);
builder.AppendUtf8WithVarIntPrefix(message);
stream.Write(builder.AsSpan());

using TempString temp = ZA.String("User ", userId, " logged in");
ReadOnlySpan<char> span = temp.AsSpan();

// Use span for parsing, comparison, logging, etc.
if (span.StartsWith("User"))
{
    Console.WriteLine(span.ToString()); // Only allocates if ToString() is called
}

using var builder = TempStringBuilder.Create();
builder.Append("User ");
builder.Append(userId);
if (isAdmin) builder.Append(" [ADMIN]");
ReadOnlySpan<char> result = builder.AsSpan();

example.code:
using var builder = TempStringBuilder.Create();
builder.Append("Hello ");
builder.Append(name);
Console.WriteLine(builder.AsSpan().ToString());

